insert into public.player_inventory(player_id,item_id) select p.id,c.item_id from public.profiles p cross join public.shop_catalog c where c.item_id like 'chibi-%' on conflict do nothing;
create or replace function public._grant_chibi_avatars() returns trigger language plpgsql security definer set search_path='' as $$
begin insert into public.player_inventory(player_id,item_id) select new.id,c.item_id from public.shop_catalog c where c.item_id like 'chibi-%' and c.active on conflict do nothing;return new;end; $$;
