create trigger grant_chibi_avatars after insert on public.profiles for each row execute function public._grant_chibi_avatars();
revoke all on function public._grant_chibi_avatars() from public,anon,authenticated;

-- Clash Bit is prepared in separate protected tables. The client feature stays hidden.
create table if not exists public.premium_wallets(player_id uuid primary key references public.profiles(id) on delete cascade,clash_bits bigint not null default 0 check(clash_bits>=0),updated_at timestamptz not null default now());
create table if not exists public.premium_credit_ledger(external_reference text primary key,player_id uuid not null references public.profiles(id),amount bigint not null check(amount>0),credited_at timestamptz not null default now());
alter table public.premium_wallets enable row level security;
alter table public.premium_credit_ledger enable row level security;
drop policy if exists premium_wallet_owner_read on public.premium_wallets;
create policy premium_wallet_owner_read on public.premium_wallets for select to authenticated using(player_id=auth.uid());
drop policy if exists premium_ledger_owner_read on public.premium_credit_ledger;
create policy premium_ledger_owner_read on public.premium_credit_ledger for select to authenticated using(player_id=auth.uid());
revoke all on public.premium_wallets,public.premium_credit_ledger from anon,authenticated;
grant select on public.premium_wallets,public.premium_credit_ledger to authenticated;
grant all on public.premium_wallets,public.premium_credit_ledger to service_role;
create or replace function public.credit_clash_bits_service(p_player uuid,p_amount bigint,p_external_reference text) returns bigint language plpgsql security definer set search_path='' as $$
declare balance bigint;existing public.premium_credit_ledger%rowtype;
begin
 if p_amount is null or p_amount<=0 or nullif(trim(p_external_reference),'') is null then raise exception 'Crédito inválido.';end if;
 perform pg_advisory_xact_lock(hashtextextended(p_external_reference,0));
 select * into existing from public.premium_credit_ledger where external_reference=p_external_reference;
 if found then
  if existing.player_id<>p_player or existing.amount<>p_amount then raise exception 'Referência já utilizada para outro crédito.';end if;
  select clash_bits into balance from public.premium_wallets where player_id=p_player;return coalesce(balance,0);
 end if;
 insert into public.premium_wallets(player_id,clash_bits) values(p_player,p_amount) on conflict(player_id) do update set clash_bits=public.premium_wallets.clash_bits+excluded.clash_bits,updated_at=now() returning clash_bits into balance;
 insert into public.premium_credit_ledger(external_reference,player_id,amount) values(p_external_reference,p_player,p_amount);return balance;
end; $$;
revoke all on function public.credit_clash_bits_service(uuid,bigint,text) from public,anon,authenticated;
grant execute on function public.credit_clash_bits_service(uuid,bigint,text) to service_role;
do $permissions$
declare p record;
begin for p in select f.oid::regprocedure signature from pg_proc f join pg_namespace n on n.oid=f.pronamespace where n.nspname='public' and left(f.proname,3)='_r_' loop execute 'revoke all on function '||p.signature||' from public,anon,authenticated';end loop;end; $permissions$;
commit;
